function trackerFor(actorState) {
  const records = new Map();
  function finish(id, error = null) {
    const record = records.get(id);
    if (!record || record.done) return;
    record.done = true;
    record.error = error ? errorText(error) : null;
    record.resolve();
  }
  const fetchImpl = async (url, init) => {
    const parsed = new URL(String(url), location.href);
    const body = typeof init?.body === "string" ? JSON.parse(init.body) : null;
    const id = Number(body?.ID);
    if (!Number.isSafeInteger(id) || id < 1) throw new Error("tracked collection fetch did not contain its request ID");
    let resolve;
    const done = new Promise((ready) => { resolve = ready; });
    records.set(id, {
      id,
      mode: parsed.searchParams.get("mode") ?? "success",
      url: parsed.href,
      done,
      resolve,
      doneState: false,
      error: null,
    });
    try {
      const response = await window.fetch(url, init);
      const text = response.text.bind(response);
      return {
        status: response.status,
        text: async () => {
          try {
            const content = await text();
            finish(id);
            return content;
          } catch (error) {
            finish(id, error);
            throw error;
          }
        },
      };
    } catch (error) {
      finish(id, error);
      throw error;
    }
  };
  return {
    records,
    fetchImpl,
    finish,
    async waitFor(id) {
      const record = records.get(id);
      if (!record) throw new Error(`no tracked fetch was started for request ${id}`);
      await record.done;
      return record.error;
    },
  };
}
